def calculate_k(x, n_a=2000, n_b=2016, window=1000):
    # A = {0, 1, ..., n_a-1}
    # B = {x, x+1, ..., x+n_b-1}
    # K = sum_{m in A} |B \cap [m-window, m+window]|
    k = 0
    for m in range(n_a):
        # Intersection of [x, x+n_b-1] and [m-window, m+window]
        start = max(x, m - window)
        end = min(x + n_b - 1, m + window)
        if start <= end:
            k += (end - start + 1)
    return k

max_k = -1
best_x = -1
for x in range(-2016, 2000):
    current_k = calculate_k(x)
    if current_k > max_k:
        max_k = current_k
        best_x = x

print(f"Max K: {max_k}, best x: {best_x}")

